#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps the tracker reachable for GC; a raw pointer was purged mid-match.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector does not see the reference and purges the object (LogGarbage at 21:05:13); the next OnGoalScored calls AddPoints on the dangling pointer -> EXCEPTION_ACCESS_VIOLATION. Fixed by making it a UPROPERTY() TObjectPtr in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is only referenced by a string path in LoadObject, so the cooker does not include it in the packaged build (bCookAll=False, only /Game/Data/Effects always cooked); LoadObject returns null and the HUD uses fallback gray. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
